import{_ as a,o as r,c as o,ag as t}from"./chunks/framework.8tqBsFWt.js";const c=JSON.parse('{"title":"Your daily view","description":"","frontmatter":{},"headers":[],"relativePath":"guide/morning-briefing.md","filePath":"guide/morning-briefing.md"}'),n={name:"guide/morning-briefing.md"};function s(i,e,h,d,l,g){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="your-daily-view" tabindex="-1">Your daily view <a class="header-anchor" href="#your-daily-view" aria-label="Permalink to &quot;Your daily view&quot;">​</a></h1><p>VERA is built around timeliness — seeing where things stand <em>now</em>, not at the end of the month. The console gives you an at-a-glance read whenever you open it. What you see depends on your role.</p><hr><h2 id="for-team-members" tabindex="-1">For team members <a class="header-anchor" href="#for-team-members" aria-label="Permalink to &quot;For team members&quot;">​</a></h2><p>Open <strong>Time</strong>. The list shows your recent entries, so a few seconds tells you whether everything&#39;s logged and nothing&#39;s slipped. Log the day&#39;s work as you go and your record stays current.</p><p>Check <strong>Time Off</strong> for the status of any holiday or leave you&#39;ve requested, and <strong>Calendar</strong> for upcoming company holidays that affect your week.</p><hr><h2 id="for-managers-and-owners" tabindex="-1">For managers and owners <a class="header-anchor" href="#for-managers-and-owners" aria-label="Permalink to &quot;For managers and owners&quot;">​</a></h2><p>The console opens on your <strong>portfolio</strong> — every project you&#39;re responsible for, with at-a-glance burn and health, so you can scan for anything drifting before it becomes a problem. From there:</p><p><strong>Envelopes</strong> — who&#39;s allocated to what, with logged-vs-remaining for each person, so you can see where capacity is tight or slack.</p><p><strong>Capacity</strong> — a forward view of how booked your team is across the coming weeks.</p><p><strong>Approvals</strong> — time-off requests waiting on you.</p><p><strong>Unresolved</strong> — items VERA has flagged that need a decision or action.</p><p><strong>Reports</strong> — estimates vs actuals, and (owners) the full financial picture: revenue recognised, cost, and margin.</p><p>Projects that are off the plan line — over or under by a meaningful margin — surface at the top with clear status flags, so the things most worth your attention find you rather than the other way round.</p><hr><h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="/blog/19-the-briefing.html">The Briefing That Replaced the Monday Check-in</a> — the thinking behind leading with timeliness, and what a daily read is actually trying to answer</li></ul>',18)])])}const m=a(n,[["render",s]]);export{c as __pageData,m as default};
